export function listConnections(config) {
    const connections = config?.connections ?? {};
    const names = Object.keys(connections);
    const configured = config?.default;
    const fallback = names.length > 0 ? (names[0] ?? null) : null;
    const defaultConnection = configured !== undefined && Object.hasOwn(connections, configured)
        ? configured
        : fallback;
    return {
        default: defaultConnection,
        items: describeConnections(connections, defaultConnection),
    };
