    if (error instanceof AuthorizationDeniedError) {
        return context.json({ code: 'FORBIDDEN', message: error.message }, 403);
    }
    if (error instanceof UserManagementError) {
        return context.json({ code: error.code, message: error.message }, error.status);
    }
    // Disabling an account can take away the last assignment of a
    // Permission Set the application must keep someone able to use.
    if (error instanceof PermissionSetLastAssignmentError) {
        return context.json({ code: 'LAST_ASSIGNMENT', message: error.message }, 409);
    }
    if (error instanceof UserRoleScopeError) {
        return context.json({ code: error.code, message: error.message }, error.status);
    }
    if (error instanceof UserAdministrationError) {
        const status = error.code === 'USER_NOT_FOUND'
            ? 404
            : error.code.endsWith('_CONFLICT')
                ? 409
                : 400;
        return context.json({ code: error.code, message: error.message }, status);
    }
    if (error instanceof UserInputError) {
        return context.json({ code: 'INVALID_USER_INPUT', message: error.message }, 400);
    }
    throw error;
